mapper.select:
SELECT id, tenant_id, user_id, connection_id, title, revision, created_at, updated_at
FROM ds_chat_session
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}

    AND connection_id = #{connectionId}


    AND (updated_at < #{cursorUpdatedAt}
         OR (updated_at = #{cursorUpdatedAt} AND id < #{cursorId}))

ORDER BY updated_at DESC, id DESC
LIMIT #{limit}

mapper.update:
UPDATE ds_chat_session
SET title = #{title}, updated_at = #{now}, revision = revision + 1
WHERE id = #{id} AND tenant_id = #{tenantId} AND user_id = #{userId}
